sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	// Skip execution when the form is loading ONLY
	if (isLoading) {
		return;
	}

	// Get the current record id
	var sysId = g_form.getUniqueValue();
	console.log("> Record ID: " + sysId.toString());

	// Get Config ID
	var configurationId = g_form.getValue("u_configuration_for");
	console.log("> Configuration for field ID: " + configurationId);

	// Assign constant values
	var HARDWARE_ID = "6286602d9388f210176f70d19dba1041";
	var CYBER_ID = "c16a50e99348f210176f70d19dba1082";

	// Comparision
	try {
		if (configurationId == HARDWARE_ID) {
			g_form.setValue("u_assignment_to", CYBER_ID);
			g_form.setMandatory("work_notes", true);
		} else {
			g_form.setValue("u_assignment_to", '');
			g_form.setMandatory("work_notes", false);
		}
	} catch (error) {
		console.error("> Error: " + error);
	}
}
